function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}
const input = items[0].json.body || items[0].json;
const sessionId = uuid();
const expiresAt = new Date(Date.now() + 1 * 24 * 60 * 60 * 1000);
const baseUrl = input.frontendUrl || items[0].json.frontendUrl || 'http://localhost:5173';
const inviteLink = `${baseUrl}/interview/${sessionId}`;
const candidateEmail = input.candidate_email || input.email;
const candidateName = input.candidate_name || input.name || 'Candidate';
if (!candidateEmail) {
  throw new Error('Missing candidate email. Send email or candidate_email in the webhook body.');
}
return {
  ...input,
  candidate_email: candidateEmail,
  candidate_name: candidateName,
  session_id: sessionId,
