const sessionId = $("Store Session").first().json.id;
const content = JSON.parse($input.first().json.choices[0].message.content);
return [{
  json: {
    session_id: sessionId,
    version: 'v1',
    competencies: content.competencies || [],
    question_plan: content.question_plan || [],
    candidate_summary: content.candidate_summary || { strengths: [], gaps: [], claims_to_validate: [] },
    constraints: content.constraints || { max_primary_questions: 10, max_follow_ups_per_question: 1 }
  }
}];

const input = $input.first().json;
const { resumeText, jdText, history, totalQuestions, analysis, authenticitySignals, lastAssessmentNote, followUpCount, pendingQuestions, allowFollowUp, planItem, maxPrimaryQuestions, maxFollowUps, targetQuestion } = input;
const truncate = (text, max) => { if (!text) return ''; return text.length > max ? text.slice(0, max) + '...[truncated]' : text; };
const INTERVIEW_PLAN = [
  { category: 'Conceptual 1 of 3', questionType: 'technical', instruction: 'Evaluate candidate\'s high-level conceptual knowledge of required tools.' },
  { category: 'Conceptual 2 of 3', questionType: 'technical', instruction: 'Assess theoretical knowledge of required tools and design patterns.' },
  { category: 'Conceptual 3 of 3', questionType: 'technical', instruction: 'Probe candidate\'s foundational engineering concepts.' },
  { category: 'Applied 1 of 2', questionType: 'technical', instruction: 'Evaluate candidate\'s hands-on project experience with required stack.' },
  { category: 'Applied 2 of 2', questionType: 'technical', instruction: 'Probe candidate\'s code implementation decisions.' },
  { category: 'Role fit / gaps 1 of 3', questionType: 'technical', instruction: 'Probe resume projects and experience transferability to JD.' },
  { category: 'Role fit / gaps 2 of 3', questionType: 'situational', instruction: 'Probe experience mismatch or domain alignment gap.' },
  { category: 'Role fit / gaps 3 of 3', questionType: 'technical', instruction: 'Probe specific tool claims and depth of usage.' },
  { category: 'Cultural fit 1 of 2', questionType: 'cultural', instruction: 'Evaluate work style preference, teamwork, and collaboration.' },
  { category: 'Cultural fit 2 of 2', questionType: 'cultural', instruction: 'Assess values, adaptability, and environment fit.' }
];
const safeTotal = (typeof totalQuestions === 'number' && !isNaN(totalQuestions)) ? totalQuestions : 0;
const stageIndex = Math.max(0, Math.min(safeTotal, 9));
const interviewStage = INTERVIEW_PLAN[stageIndex] || INTERVIEW_PLAN[0];
let focusInstruction = '';
const extractedTools = analysis?.extractedTools || [];
if (planItem) {
  if (planItem.category === 'gap_probe') {
    const gap = planItem.gap_ref;
    focusInstruction = `CATEGORY: gap_probe — Probe a potential gap: \"${gap?.description || planItem.objective}\". Probe direction: \"${gap?.probe_direction || 'Ask how experience transfers'}\". TONE: Warm, curious, curious, recruiter frame.`;
  } else if (planItem.category === 'problem_solving') {
    focusInstruction = `CATEGORY: problem_solving — Scenario reasoning. Objective: ${planItem.objective || 'Trade-off analysis'}. Scenario testing.`;
  } else if (planItem.category === 'cultural') {
    focusInstruction = `CATEGORY: cultural — Assess work style. Objective: ${planItem.objective || 'teamwork/collaboration'}`;
  } else {
    const tool = planItem.target_tool || 'the required skill';
    const mode = planItem.verification_mode || 'baseline_check';
    const matchingToolObj = extractedTools.find(t => t.name.toLowerCase() === tool.toLowerCase());
    const resumeContext = matchingToolObj?.resume_context || '';
    if (mode === 'verify_claim') {
      focusInstruction = `VERIFICATION MODE: verify_claim — claims experience with \"${tool}\"${resumeContext ? ` (\"${resumeContext}\")` : ''}. Ask for their OWN practical usage. Objective: ${planItem.objective}`;
    } else {
      focusInstruction = `VERIFICATION MODE: baseline_check — \"${tool}\" required by JD but not on resume. Ask simple baseline awareness question. Objective: ${planItem.objective}`;
    }
  }
} else {
  focusInstruction = interviewStage.instruction;
}
const lastItem = history && history.length > 0 ? history[history.length - 1] : null;
const lastAnswer = lastItem?.answer || '';
const prevType = lastItem?.type || '';
const nextType = planItem?.question_type || interviewStage.questionType || 'technical';
const isPrevTechOrSituational = prevType === 'technical' || prevType === 'situational';
const isNextSituationalOrCultural = nextType === 'situational' || nextType === 'cultural' || nextType === 'behavioral';
const useSimpleAck = isPrevTechOrSituational && isNextSituationalOrCultural;
const instruction1 = useSimpleAck
  ? `1. TRANSITION RULE: Because you are transitioning from a ${prevType} question to a ${nextType} question, you MUST acknowledge the last answer with exactly \"Got it, thank you.\" (do not analyze, detail, or repeat details from their last answer). Then smoothly transition to the next question.`
  : `1. ACKNOWLEDGE the candidate's MOST RECENT answer (to \"${lastItem?.question || 'their last question'}\") naturally — reference a specific detail they shared in that answer. Do NOT reference earlier questions or use generic acknowledgments like \"Great answer\" or \"Thanks\".`;
const recentAuthSignals = authenticitySignals || [];
const hasRecentRedFlags = recentAuthSignals.some(s => s.signal === 'suspicious' || s.signal === 'inconsistent');
const hasRecentVague = recentAuthSignals.some(s => s.signal === 'vague');
const authenticityContext = recentAuthSignals.length > 0 ? `\nRecent signals:\n${recentAuthSignals.map(s => `- Signal: ${s.signal} / Depth: ${s.depth}`).join('\n')}\n${hasRecentRedFlags ? '⚠️ Probe details.' : ''}` : '';
const alreadyAskedQText = (history || []).map((h, i) => `${i + 1}. ${h.question}`).join('\n') || 'None.';
const isNoteMatchingLastItem = Boolean(lastAssessmentNote && lastAssessmentNote.question_id && lastItem && lastItem.id && lastAssessmentNote.question_id === lastItem.id);
const validNote = isNoteMatchingLastItem ? lastAssessmentNote?.note : undefined;
const lastAnswerContext = lastItem ? `\nMOST RECENT CANDIDATE ANSWER TO ACKNOWLEDGE:\n- Question: \"${lastItem.question}\"\n- Answer: \"${lastAnswer || '(no response)'}\"${validNote ? `\n- Assessment: \"${validNote}\"` : ''}` : '';
const pendingContext = (pendingQuestions || []).length > 0 ? `\nPending questions:\n${pendingQuestions.map((q, i) => `  ${i + 1}. ${q}`).join('\n')}` : '';
const targetQuestionContext = targetQuestion ? `\nREQUIRED NEXT QUESTION: \"${targetQuestion}\"\nYou MUST ask this specific question next. Prefix it with a warm acknowledgment.` : '';
const prompt = `You are Alex, a warm but sharp recruiter. Respond in character.\n\nResume:\n${truncate(resumeText, 2500)}\n\nJD:\n${truncate(jdText, 2500)}\n\nHistory:\n${alreadyAskedQText}\n${lastAnswerContext}\n\n${pendingContext}\n${targetQuestionContext}\n\nCurrent stage:\n- Category: ${interviewStage.category}\n- Focus: ${focusInstruction}\n- Required type: ${interviewStage.questionType}\n\nINSTRUCTIONS:\n${instruction1}\n${lastItem?.type === 'follow_up' ? '2. POST-FOLLOW-UP RULE: Acknowledge in one sentence, then ask next question. Do NOT ask another follow-up.\n3.' : '2.'} Ask the REQUIRED NEXT QUESTION if provided. Otherwise, ask a plan question.\n3. Warm transition. Sound human.\n4. Keep it to one question.\n\nReturn ONLY this JSON:\n{\n  \"interviewer_text\": \"Your utterance\",\n  \"question_text\": \"Question part only\",\n  \"turn_type\": \"question\" | \"follow_up\" | \"transition\" | \"closing\",\n  \"question_type\": \"technical\" | \"behavioral\" | \"situational\" | \"cultural\",\n  \"should_continue\": true\n}`;
return [{ json: { prompt } }];

const input = $input.first().json;
const { originalQuestion, candidateAnswer, insufficiencyReason, gapDirection, resumeText, jdText } = input;
const gapStrategy = {
  lacks_depth: 'The candidate described WHAT happened but not HOW or WHY. Ask for the underlying mechanism, reasoning, or trade-off — e.g. "Why did you choose that approach over alternatives?" or "What specifically made X the right decision here?"',
  lacks_evidence: 'The candidate made a claim with no concrete proof. Ask for a specific metric, number, project name, or verifiable example — e.g. "What was the before/after measurement?" or "Can you give me a specific project where you applied that?"',
  vague: 'The candidate was hedgy, generic, or buzzword-heavy. Ask for a single, specific named instance — a tool name, a command, a team size, a decision, a number — something only someone who actually did it could provide.',
  irrelevant: 'The candidate's answer did not address the question. Gently redirect by rephrasing the original question more concretely, zeroing in on the specific capability you were testing.'
};
const prompt = `You are Alex, a warm but sharp senior technical recruiter. The candidate just gave a technically insufficient answer that requires a targeted follow-up probe.

Original question you asked:
"${originalQuestion}"

Candidate's answer:
"${candidateAnswer}"

Failure mode detected: ${insufficiencyReason}
Gap to probe: ${gapDirection}
Strategy for this failure mode: ${gapStrategy[insufficiencyReason]}

Resume excerpt (for context):
${resumeText?.slice(0, 400) || 'Not available'}

